#!/bin/bash
set -euo pipefail
/data1/home/sunyiq/miniconda3/envs/nh_final/bin/python -I -B - <<'WEIGHT_EXPORT'

import base64, hashlib, json, tarfile
from io import BytesIO
from pathlib import Path, PurePosixPath
PLAN = json.loads(base64.b64decode(''))
def sha(raw): return hashlib.sha256(raw).hexdigest()
roots = PLAN['roots']
for source, spec in roots.items():
    root = Path(spec['remote_root'])
    if root.is_symlink() or not root.is_dir(): raise ValueError('exclusive root differs')
    if sha((root/'registry_frozen.json').read_bytes()) != spec['registry_sha256']:
        raise ValueError('registered source identity differs')
    if sha((root/'reports/training_manifest.json').read_bytes()) != spec['manifest_sha256']:
        raise ValueError('registered manifest identity differs')
memory = BytesIO()
total = 0
with tarfile.open(fileobj=memory, mode='w:gz') as archive:
    for entry in PLAN['weights']:
        checkpoint = entry['checkpoint']
        name = PurePosixPath(checkpoint['relative_path'])
        if (name.is_absolute() or '..' in name.parts or '\\' in str(name)
                or len(name.parts)!=4 or name.parts[0]!='runs'
                or name.parts[1]!=entry['run']['exp_id'] or name.parts[2]!='checkpoints'
                or name.suffix!='.pt'):
            raise ValueError('path is not an exact registered epoch weight')
        root = Path(roots[entry['source']]['remote_root'])
        path = root.joinpath(*name.parts)
        if path.is_symlink() or not path.is_file() or path.stat().st_size!=checkpoint['bytes']:
            raise ValueError('selected file missing or different size')
        epoch = root/'runs'/entry['run']['exp_id']/(path.stem+'.json')
        record = json.loads(epoch.read_bytes())
        if record['checkpoint']!=checkpoint or record['experiment_id']!=entry['run']['exp_id']:
            raise ValueError('epoch record and planned weight differ')
        raw = path.read_bytes()
        if sha(raw)!=checkpoint['sha256']: raise ValueError('selected weight hash differs')
        total += len(raw)
        if total>5500000: raise ValueError('raw export exceeds frozen part bound')
        member = tarfile.TarInfo(entry['source']+'/'+name.as_posix())
        member.size=len(raw)
        archive.addfile(member, BytesIO(raw))
bundle=memory.getvalue()
if len(bundle)>5900000: raise ValueError('compressed export exceeds part bound')
print('WEIGHT_AUDIT '+json.dumps({'status':'EXACT_REGISTERED_WEIGHTS_EXPORTED',
    'part':PLAN['part'],'models_sha256':PLAN['models_sha256'],
    'plan_sha256':sha(json.dumps(PLAN,sort_keys=True,separators=(',',':'),allow_nan=False).encode()),
    'members':len(PLAN['weights']),'raw_bytes':total,'bundle_bytes':len(bundle),
    'bundle_sha256':sha(bundle)},sort_keys=True))
print('WEIGHT_BASE64 '+base64.b64encode(bundle).decode())

WEIGHT_EXPORT
